require_once __DIR__.'/config.php';require_roles(['technician']);$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);$st=$pdo->prepare('SELECT * FROM equipment WHERE id=? AND assigned_technician_id=?');$st->execute([$id,(int)$_SESSION['user_id']]);$asset=$st->fetch();if(!$asset){http_response_code(404);exit('This equipment is not assigned to your account.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=trim((string)($_POST['status']??''));$condition=trim((string)($_POST['condition_note']??''));$note=trim((string)($_POST['work_note']??''));if(!in_array($status,statuses(),true))$errors[]='Choose a valid status.';if(!in_array($condition,conditions(),true))$errors[]='Choose a valid condition.';if(!$errors){$st=$pdo->prepare('UPDATE equipment SET status=?,condition_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND assigned_technician_id=?');$st->execute([$status,$condition,$id,(int)$_SESSION['user_id']]);if($note!==''){$st=$pdo->prepare("INSERT INTO maintenance(equipment_id,maintenance_date,maintenance_type,performed_by,cost,details) VALUES(?,date('now'),'Inspection',?,0,?)");$st->execute([$id,$_SESSION['full_name'],$note]);}flash('Assigned equipment status updated.');redirect('equipment.php');}}
$pageTitle='Update assigned equipment';require 'header.php';
?><div class="page-heading"><div><div class="eyebrow">TECHNICIAN UPDATE</div><h1><?=e($asset['name'])?></h1><p><?=e($asset['asset_tag'])?> · <?=e($asset['location'])?></p></div><a class="btn secondary" href="equipment.php">← Back</a></div><?php if($errors):?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif;?><section class="panel"><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Equipment status</label><select name="status"><?php foreach(statuses() as $s):?><option <?=$asset['status']===$s?'selected':''?> value="<?=e($s)?>"><?=e($s)?></option><?php endforeach;?></select><label>Physical condition</label><select name="condition_note"><?php foreach(conditions() as $c):?><option <?=$asset['condition_note']===$c?'selected':''?> value="<?=e($c)?>"><?=e($c)?></option><?php endforeach;?></select><label>Work note (optional)</label><textarea name="work_note" rows="4" placeholder="Describe the inspection or status change"></textarea><button class="btn primary" type="submit">Save update</button></form></section><?php require 'footer.php';?>